495	     *  rule (open, settle, void and close by clerk and steward; reassign and reopen by steward). A viewer takes none,
496	     *  and no one takes any on an archived sheet. */
497	    public boolean allows(String sheetId, String user, String action) {
498	        if (sheets.archived(sheetId)) {
499	            return false;
500	        }
501	        String role = role(sheetId, user);
502	        if (VIEWER.equals(role)) {
503	            return false;
504	        }
505	        String set = permission(sheetId, action);
506	        if (set.isEmpty()) {
507	            return STEWARD.equals(role) || !("reassign".equals(action) || "reopen".equals(action));
508	        }
509	        return List.of(set.split(",")).contains(role);
