512	    /** The sheet's settings as shown: each dated one as in force on the sheet's today — the clerk limit ("" for none),
513	     *  the floor, the terms, the late percent, each grade's own terms (a grade with none then is left out) and the cap
514	     *  ("" for none) — the proof threshold ("" for none), the policy date ("" for blank), the period numbering from ("" for off), every role set, by user
515	     *  name, every value recorded for the dated settings and each action's permission ("" for the standing rule), and the grace days ("" for off), and every delegation of the steward role, in the order given. */
516	    public SettingsResponse load(String sheetId) {
517	        LocalDate today = sheets.today(sheetId);
518	        BigDecimal limit = clerkLimit(sheetId);
519	        BigDecimal cap = cap(sheetId);
520	        BigDecimal threshold = proofThreshold(sheetId, today);
521	        BigDecimal noteThreshold = noteThreshold(sheetId, today);
522	        BigDecimal reviewThreshold = reviewThreshold(sheetId, today);
523	        InForce rounding = on(sheetId, ValidateSetting.ROUNDING, today);
524	        LocalDate policy = policyDateSet(sheetId);
525	        LocalDate numbering = periodNumberingFrom(sheetId);
526	        Integer grace = graceDays(sheetId);
527	        Integer escalate = escalateAfter(sheetId);
528	        Integer reviewSla = reviewSla(sheetId);
529	        Integer maxOpen = maxOpen(sheetId);
530	        Integer pendingSla = pendingSla(sheetId);
531	        Integer scoreMid = scoreThreshold(sheetId, ValidateSetting.SCORE_MID);
532	        Integer scoreHigh = scoreThreshold(sheetId, ValidateSetting.SCORE_HIGH);
533	        LocalDate entry = entryDate(sheetId);
534	        BigDecimal pot = pot(sheetId);
535	        BigDecimal alert = alertThreshold(sheetId);
536	        String parent = parent(sheetId);
537	        List<RoleResponse> roles = jdbc.query(
538	                "SELECT user_name, role FROM sheet_role WHERE sheet_id = ? ORDER BY user_name",
539	                (rs, i) -> new RoleResponse(rs.getString(1), rs.getString(2)), sheetId);
540	        java.util.Map<String, String> gradeTerms = new java.util.TreeMap<>();
541	        for (String grade : grades.codes(sheetId)) {
542	            Integer own = gradeTerms(sheetId, grade, today);
543	            if (own != null) {
544	                gradeTerms.put(grade, String.valueOf(own));
545	            }
546	        }
547	        java.util.Map<String, String> perms = new java.util.LinkedHashMap<>();
548	        for (String action : ValidateSetting.ACTIONS) {
549	            perms.put(action, permission(sheetId, action));
550	        }
551	        return new SettingsResponse(limit == null ? "" : limit.setScale(2).toPlainString(),
552	                floor(sheetId, today).setScale(2).toPlainString(), String.valueOf(terms(sheetId, today)),
553	                latePct(sheetId, today).setScale(2).toPlainString(), policy == null ? "" : policy.toString(),
554	                numbering == null ? "" : numbering.toString(), roles, gradeTerms,
555	                cap == null ? "" : cap.setScale(2).toPlainString(), dated(sheetId),
556	                threshold == null ? "" : threshold.setScale(2).toPlainString(), perms,
557	                grace == null ? "" : String.valueOf(grace), jdbc.query(
558	                        "SELECT user_name, from_date, to_date, delegated_by FROM sheet_delegation WHERE sheet_id = ? ORDER BY seq",
559	                        (rs, i) -> new DelegationResponse(rs.getString(1), rs.getDate(2).toLocalDate().toString(),
560	                                rs.getDate(3).toLocalDate().toString(), rs.getString(4)), sheetId),
561	                noteThreshold == null ? "" : noteThreshold.setScale(2).toPlainString(), entry == null ? "" : entry.toString(), pot == null ? "" : pot.toPlainString(),
562	                parent == null ? "" : parent, String.valueOf(fiscalStartMonth(sheetId)),
563	                alert == null ? "" : alert.toPlainString(), rounding == null ? "" : net.officefloor.hq.app.claim.Rounding.name(rounding.value()),
564	                reviewThreshold == null ? "" : reviewThreshold.setScale(2).toPlainString(),
565	                escalate == null ? "" : String.valueOf(escalate), reviewSla == null ? "" : String.valueOf(reviewSla),
566	                String.join(",", proofKinds(sheetId)), Objects.toString(defaultGradeSet(sheetId), ""),
567	                scoreMid == null ? "" : String.valueOf(scoreMid), scoreHigh == null ? "" : String.valueOf(scoreHigh),
568	                scoreLog(sheetId) ? "on" : "", maxOpen == null ? "" : String.valueOf(maxOpen),
569	                pendingSla == null ? "" : String.valueOf(pendingSla));
570	    }
