  const statusCount = (s: (typeof STATUSES)[number]) => sheetClaims.filter((c) => c.status === s).length;
  // Review-late: REVIEW claims whose review day plus the sheet's review SLA is before the sheet's today.
  const reviewLateCount = sheetClaims.filter((c) => isReviewLate(c, today, reviewSla)).length;
  // Pending-late: PENDING claims whose pending day plus the sheet's pending SLA is before the sheet's today.
  const pendingLateCount = sheetClaims.filter((c) => isPendingLate(c, today, pendingSla)).length;
  const voidReasonCount = (reason: string) => sheetClaims.filter((c) => c.status === 'VOID' && c.voidReason === reason).length;
  return { people, claims, rates, today, byId, live, claimedLive, cutOf, totalOf, excessOf, overdue, overdueTotal, dueFigures, overdueFigures, sheetDueTotal, sheetOverdueTotal, statusCount, reviewLateCount, pendingLateCount, voidReasonCount, isActive, recentSettledOf, agedOf, sheetAged, settledTotalOf, openTotalOf, scoreOf, sheetSettledTotal, sheetOpenTotal, sheetCutTotal, settledFigures, openFigures, cutFigures, tagTotals, monthTotals };
}

// People's figures added up, leaving out the single highest and the single lowest when there are
// three or more.
export function trimmedSum(figures: bigint[]): bigint {
  const sum = figures.reduce((a, b) => a + b, 0n);
  if (figures.length < 3) return sum;
  const max = figures.reduce((a, b) => (b > a ? b : a));
  const min = figures.reduce((a, b) => (b < a ? b : a));
  return sum - max - min;
}

// The ISO date `days` days before `date`.
function daysBefore(date: string, days: number): string {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() - days);
  return d.toISOString().slice(0, 10);
}

// The whole days from one ISO date to a later one (negative when it is earlier).
function daysBetween(from: string, to: string): number {
  return Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86_400_000);
}

// n / d (d > 0) rounded half up (away from zero) or else half to even.
function roundDiv(n: bigint, d: bigint, halfUp: boolean): bigint {
  if (!halfUp) return halfEvenDiv(n, d);
  const abs = n < 0n ? -n : n;
  const q = (abs * 2n + d) / (2n * d);
  return n < 0n ? -q : q;
}

// n / d (d > 0) rounded half to even.
function halfEvenDiv(n: bigint, d: bigint): bigint {
  let q = n / d;
  let r = n % d;
  if (r < 0n) {
    q -= 1n;
    r += d;
  }
  if (r * 2n > d || (r * 2n === d && q % 2n !== 0n)) q += 1n;
  return q;
}
